  max-width: 38rem;
  margin: 0 auto 1.5rem auto;
  background-color: #ffffff;
  border: 1px solid #d7e6d4;
  border-radius: 8px;
  padding: 1.25rem;
}

button {
  display: block;
  margin: 0 auto;
  padding: 0.6rem 1.2rem;
  background-color: #3c7a3c;
  color: #ffffff;
  border: none;
  border-radius: 6px;
  cursor: pointer;
}

button:hover {
  background-color: #2f5f2f;
}
"}

